  // Playback engine
  function updateProgress() {
    const pct = steps.length ? (stepIdx / steps.length) * 100 : 0;
    $("#mk-timeline-fill").style.width = pct + "%";
    const s = steps[stepIdx];
    // Show a friendly stage label · never the step count (would betray playback mode)
    $("#mk-step-label").textContent = s ? _friendlyLabel(s.label) : "已完成";
  }
  // Strip prefixes like "Gen 1 · " and step counters from raw step labels
  function _friendlyLabel(lbl) {
    if (!lbl) return "";
    // Drop "Gen N · " prefix
    return lbl.replace(/^Gen\s+\d+\s+·\s*/, "").replace(/^等待确认\s*·\s*/, "等待确认 · ");
  }

  async function runStep() {
    const s = steps[stepIdx];
    if (!s) { pause(); return; }
    updateProgress();
    const dur = Math.max(120, s.dur / speed);
    const myToken = resetToken;
    if (s.streaming) {
      await s.fn({speed});
    } else {
      await s.fn();
      await new Promise(res => setTimeout(res, dur));
    }
    // If a reset fired while this step was awaiting, don't bump stepIdx
    if (myToken !== resetToken) return;
    stepIdx++;
    updateProgress();
  }

  async function playLoop() {
    while (playing && stepIdx < steps.length) {
      await runStep();
    }
    playing = false;
    $("#mk-play").textContent = stepIdx >= steps.length ? "🔁 重来" : "▶ 开始";
  }

  function play() {
    if (stepIdx >= steps.length) reset();
    playing = true;
    stopSignal = false;
    $("#mk-play").textContent = "⏸ 暂停";
    startElapsed();
    playLoop();
  }
  function pause() {
    playing = false; stopSignal = true;
